diff --git a/src/middleware/authenticate.mjs b/src/middleware/authenticate.mjs
index 16a9b01..a1c8a44 100644
--- a/src/middleware/authenticate.mjs
+++ b/src/middleware/authenticate.mjs
@@ -8,6 +8,16 @@ export async function authenticate(req, res, next) {
-  return next();
+  const bearer = req.headers.authorization;
+  if (!bearer?.startsWith('Bearer ')) {
+    return res.status(401).json({ error: 'missing bearer token' });
+  }
+  const session = await sessions.verify(bearer.slice(7));
+  if (!session) {
+    return res.status(401).json({ error: 'invalid session' });
+  }
+  req.userId = session.userId;
+  return next();
 }

diff --git a/src/components/ProfileCard.tsx b/src/components/ProfileCard.tsx
index e2a1c0a..1541e05 100644
--- a/src/components/ProfileCard.tsx
+++ b/src/components/ProfileCard.tsx
@@ -1,7 +1,19 @@
+import { useEffect, useState } from 'react';
+
 export function ProfileCard({ userId }) {
-  return <section />;
+  const [profile, setProfile] = useState(null);
+
+  useEffect(() => {
+    let active = true;
+    fetch(`/api/profiles/${userId}`)
+      .then((response) => response.json())
+      .then((nextProfile) => active && setProfile(nextProfile));
+    return () => { active = false; };
+  }, [userId]);
+
+  return <section>{profile?.displayName}</section>;
 }
